const unsuppressCustomer = `-- name: UnsuppressCustomer :exec
DELETE FROM communication_suppressions WHERE user_id = $1
`

func (q *Queries) UnsuppressCustomer(ctx context.Context, userID pgtype.UUID) error {
	_, err := q.db.Exec(ctx, unsuppressCustomer, userID)
	return err
}

